import React, { useState, useEffect } from 'react';
import { AgGridReact } from 'ag-grid-react';
import { searchTracks, getTrackWithGenre } from '../services/api';
import 'ag-grid-community/styles/ag-grid.css';
import 'ag-grid-community/styles/ag-theme-alpine.css';

const TrackSearch = ({ searchTerm }) => {
  const [filteredTracks, setFilteredTracks] = useState([]);
  const [rowData, setRowData] = useState([]);

  useEffect(() => {
    if (searchTerm) {
      searchTracks(searchTerm).then(async tracks => {
        setFilteredTracks(tracks);

        const detailsArray = await Promise.all(
          tracks.map(async track => {
            const details = await getTrackWithGenre(track.id);
            return { ...track, ...details };
          })
        );

        setRowData(detailsArray);
      }).catch(error => console.error('Error fetching tracks:', error));
    }
  }, [searchTerm]);

  const columnDefs = [
    { headerName: 'Track Name', field: 'name', minWidth: 150, flex: 1 },
    { headerName: 'Artist Name', field: 'artists[0].name', minWidth: 150, flex: 1 },
    { headerName: 'Album Name', field: 'album.name', minWidth: 150, flex: 1 },
    { headerName: 'Release Date', field: 'album.release_date', minWidth: 100, flex: 1, valueFormatter: params => params.value ? params.value.split('-')[0] : 'Unknown' },
    { headerName: 'Tempo', field: 'tempo', minWidth: 100 },
    { headerName: 'Key', field: 'key', minWidth: 80 },
    { headerName: 'Danceability', field: 'danceability', minWidth: 120 },
    { headerName: 'Energy', field: 'energy', minWidth: 100 },
    { headerName: 'Valence', field: 'valence', minWidth: 100 },
    { headerName: 'Acousticness', field: 'acousticness', minWidth: 130 },
    { headerName: 'Instrumentalness', field: 'instrumentalness', minWidth: 150 },
    { headerName: 'Liveness', field: 'liveness', minWidth: 100 },
    { headerName: 'Genre', field: 'genres', minWidth: 150, valueFormatter: params => params.value ? params.value.join(', ') : 'N/A' },
    { 
      headerName: 'Preview', 
      field: 'preview', 
      minWidth: 240, 
      cellRendererFramework: params => 
        params.data.id ? (
          <iframe
            src={`https://open.spotify.com/embed/track/${params.data.id}`}
            width="100%"
            height="80"
            allow="encrypted-media"
            style={{ border: 'none' }}
          ></iframe>
        ) : 'No Preview'
    }
  ];

  return (
    <div className="ag-theme-alpine" style={{ height: '100vh', width: '100%', marginTop: '20px' }}>
      <AgGridReact
        rowData={rowData}
        columnDefs={columnDefs}
        domLayout="autoHeight"
        defaultColDef={{
          resizable: true,
          sortable: true,
        }}
      />
    </div>
  );
};

export default TrackSearch;
